<section class="panel"><div class="panel-heading"><div><h2>Player directory</h2><p><?=h(number_format($dashboard['total']))?> matching player(s). Select a player to edit their wardrobe.</p></div></div><form method="get" class="inline-form"><input type="hidden" name="page" value="players"><label class="grow">Search by UUID<input name="q" value="<?=h($dashboard['search'])?>" maxlength="36" placeholder="Paste a UUID or part of one"></label><button>Search</button><?php if($dashboard['search']!==''):?><a class="button ghost" href="<?=h(AdminDashboard::url('players'))?>">Clear</a><?php endif?></form>
